class Solution {
public:
    long long countMajoritySubarrays(vector<int>& nums, int target) {
        int n = nums.size();
        long long count = 0;

        for (int i = 0; i < n; i++) {
            int freq = 0;
            for (int j = i; j < n; j++) {
                if (nums[j] == target) {
                    freq++;
                }
                if (2 * freq > j - i + 1) {
                    count++;
                }
            }
        }

        return count;
    }
};

